/**
 * inline.mjs — Inline-level Markdown parser modeled after Python-Markdown.
 *
 * Zero-dependency ESM. All matching is done with explicit character
 * scanning; no RegExp or regex-related APIs are used anywhere.
 *
 * Exports:
 *   parseInline(text, context = {})        -> HTML string
 *   plainTextForInline(text, options = {}) -> plain text for TOC
 *       options.forSlug: decode entities, raw output (for slugify)
 *       default: TOC-HTML mode (tags stripped, entities kept as written,
 *       HTML-safe output)
 *
 * context shape (all optional):
 *   { references, abbreviations, footnoteRef, state, extensions }
 * `state` may carry `references` / `abbreviations` as a fallback.
 * references: Map or plain object of normalized label ->
 *   [url, title] | {url, title} | {href, title} | "url"
 * abbreviations: Map or plain object of term -> title
 * footnoteRef(key): returns footnote reference HTML (or null)
 */

// ---------------------------------------------------------------------------
// Character helpers
// ---------------------------------------------------------------------------

// Backslash-escapable punctuation (Python-Markdown ESCAPED_CHARS).
const ESCAPABLE = '\\`*_{}[]()#+-.!>';

function isEscapable(ch) {
  return ESCAPABLE.indexOf(ch) !== -1;
}

function isWhitespace(ch) {
  return ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r' || ch === '\f';
}

function isAsciiDigit(ch) {
  return ch >= '0' && ch <= '9';
}

function isAsciiLetter(ch) {
  return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z');
}

function isAsciiAlnum(ch) {
  return isAsciiLetter(ch) || isAsciiDigit(ch);
}

function isHexDigit(ch) {
  return isAsciiDigit(ch) || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F');
}

// Python \w with unicode strings: ASCII alnum + underscore plus most
// non-ASCII letters. CJK/general punctuation is treated as non-word.
function isWordChar(ch) {
  if (!ch) return false;
  if (isAsciiAlnum(ch) || ch === '_') return true;
  const code = ch.codePointAt(0);
  if (code < 0x80) return false;
  if (code >= 0x2000 && code <= 0x206f) return false; // general punctuation
  if (code >= 0x3000 && code <= 0x303f) return false; // CJK punctuation
  if (code >= 0xff01 && code <= 0xff0f) return false; // fullwidth punctuation
  return true;
}

// ---------------------------------------------------------------------------
// Escaping
// ---------------------------------------------------------------------------

// Normal text: valid entities are preserved, bare & < > are escaped.
// Code / attributes: & < > " are always escaped.

// If a valid entity starts at src[i] (which must be '&'), return its full
// length including '&' and ';', else 0. Valid forms: &alnum+; &#digits;
// &#xHex; / &#XHex;
function entityLengthAt(src, i) {
  const n = src.length;
  let j = i + 1;
  if (j >= n) return 0;
  if (src[j] === '#') {
    j++;
    if (j < n && (src[j] === 'x' || src[j] === 'X')) {
      j++;
      const start = j;
      while (j < n && isHexDigit(src[j])) j++;
      if (j === start || j >= n || src[j] !== ';') return 0;
      return j - i + 1;
    }
    const start = j;
    while (j < n && isAsciiDigit(src[j])) j++;
    if (j === start || j >= n || src[j] !== ';') return 0;
    return j - i + 1;
  }
  const start = j;
  while (j < n && isAsciiAlnum(src[j])) j++;
  if (j === start || j >= n || src[j] !== ';') return 0;
  return j - i + 1;
}

function escapeText(s) {
  let out = '';
  let i = 0;
  const n = s.length;
  while (i < n) {
    const ch = s[i];
    if (ch === '&') {
      const len = entityLengthAt(s, i);
      if (len > 0) {
        out += s.slice(i, i + len);
        i += len;
      } else {
        out += '&amp;';
        i++;
      }
    } else if (ch === '<') {
      out += '&lt;';
      i++;
    } else if (ch === '>') {
      out += '&gt;';
      i++;
    } else {
      out += ch;
      i++;
    }
  }
  return out;
}

// Escape & < > always (no entity preservation). Used for code content in
// TOC plain mode.
function escapeTextAll(s) {
  let out = '';
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (ch === '&') out += '&amp;';
    else if (ch === '<') out += '&lt;';
    else if (ch === '>') out += '&gt;';
    else out += ch;
  }
  return out;
}

// Code spans and attribute values: & < > " all escaped.
function escapeAll(s) {
  let out = '';
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (ch === '&') out += '&amp;';
    else if (ch === '<') out += '&lt;';
    else if (ch === '>') out += '&gt;';
    else if (ch === '"') out += '&quot;';
    else out += ch;
  }
  return out;
}

// ---------------------------------------------------------------------------
// Entity decoding (for slug mode)
// ---------------------------------------------------------------------------

const NAMED_ENTITIES = {
  amp: '&', lt: '<', gt: '>', quot: '"', apos: "'",
  nbsp: ' ', copy: '©', reg: '®', trade: '™', deg: '°',
  hellip: '…', mdash: '—', ndash: '–', laquo: '«', raquo: '»',
  times: '×', divide: '÷', plusmn: '±', para: '¶', sect: '§',
  middot: '·', bull: '•', dagger: '†', Dagger: '‡', permil: '‰',
  prime: '′', Prime: '″', euro: '€', pound: '£', yen: '¥',
  cent: '¢', curren: '¤', brvbar: '¦', uml: '¨', ordf: 'ª', ordm: 'º',
  iexcl: '¡', iquest: '¿', szlig: 'ß', micro: 'µ', sup1: '¹',
  sup2: '²', sup3: '³', frac12: '½', frac14: '¼', frac34: '¾',
  AElig: 'Æ', aelig: 'æ', Oslash: 'Ø', oslash: 'ø', Ccedil: 'Ç',
  ccedil: 'ç', Ntilde: 'Ñ', ntilde: 'ñ', lsquo: '‘', rsquo: '’',
  ldquo: '“', rdquo: '”', larr: '←', uarr: '↑', rarr: '→',
  darr: '↓', harr: '↔', minus: '−', lowast: '∗', ne: '≠',
  le: '≤', ge: '≥', asymp: '≈', equiv: '≡', infin: '∞',
};

// body is the text between '&' and ';'. Returns decoded string or null.
function decodeEntityBody(body) {
  if (!body) return null;
  if (body[0] === '#') {
    let num;
    if (body.length > 1 && (body[1] === 'x' || body[1] === 'X')) {
      num = 0;
      for (let i = 2; i < body.length; i++) {
        if (!isHexDigit(body[i])) return null;
        num = num * 16 + parseInt(body[i], 16);
      }
    } else {
      num = 0;
      for (let i = 1; i < body.length; i++) {
        if (!isAsciiDigit(body[i])) return null;
        num = num * 10 + (body[i].charCodeAt(0) - 48);
      }
    }
    if (num <= 0 || num > 0x10ffff) return null;
    try {
      return String.fromCodePoint(num);
    } catch (err) {
      return null;
    }
  }
  if (Object.prototype.hasOwnProperty.call(NAMED_ENTITIES, body)) {
    return NAMED_ENTITIES[body];
  }
  return null;
}

// ---------------------------------------------------------------------------
// Misc text helpers
// ---------------------------------------------------------------------------

function normalizeNewlines(s) {
  let out = '';
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (ch === '\r') {
      if (s[i + 1] === '\n') continue; // drop \r of \r\n
      out += '\n';
    } else {
      out += ch;
    }
  }
  return out;
}

// Process backslash escapes in a raw fragment (URLs, titles, alt text):
// "\<escapable>" becomes the char, other backslashes are kept.
function processEscapes(s) {
  let out = '';
  for (let i = 0; i < s.length; i++) {
    if (s[i] === '\\' && i + 1 < s.length && isEscapable(s[i + 1])) {
      out += s[i + 1];
      i++;
    } else {
      out += s[i];
    }
  }
  return out;
}

// Reference label normalization: trim, collapse whitespace runs to a single
// space, lowercase.
function normalizeLabel(s) {
  let out = '';
  let pendingSpace = false;
  let started = false;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (isWhitespace(ch)) {
      if (started) pendingSpace = true;
    } else {
      if (pendingSpace) {
        out += ' ';
        pendingSpace = false;
      }
      out += ch.toLowerCase();
      started = true;
    }
  }
  return out;
}

// ---------------------------------------------------------------------------
// Context resolution
// ---------------------------------------------------------------------------

function resolveContext(context) {
  const ctx = { references: null, abbreviations: null, footnoteRef: null };
  if (!context) return ctx;
  const state = context.state || null;
  ctx.references = context.references || (state && state.references) || null;
  ctx.abbreviations =
    context.abbreviations || (state && state.abbreviations) || null;
  if (typeof context.footnoteRef === 'function') {
    ctx.footnoteRef = context.footnoteRef.bind(context);
  }
  return ctx;
}

function mapGet(mapish, key) {
  if (!mapish) return undefined;
  if (typeof mapish.get === 'function') return mapish.get(key);
  if (Object.prototype.hasOwnProperty.call(mapish, key)) return mapish[key];
  return undefined;
}

function mapEntries(mapish) {
  if (!mapish) return [];
  if (typeof mapish.entries === 'function') {
    const out = [];
    for (const pair of mapish.entries()) out.push(pair);
    return out;
  }
  return Object.keys(mapish).map((k) => [k, mapish[k]]);
}

// Normalize a reference value to {url, title} or null.
function normalizeReferenceValue(value) {
  if (value == null) return null;
  if (typeof value === 'string') return { url: value, title: null };
  if (Array.isArray(value)) {
    return { url: value[0] != null ? String(value[0]) : '', title: value[1] != null ? String(value[1]) : null };
  }
  if (typeof value === 'object') {
    const url = value.url != null ? value.url : value.href;
    if (url == null) return null;
    return { url: String(url), title: value.title != null ? String(value.title) : null };
  }
  return null;
}

function lookupReference(ctx, label) {
  if (!ctx || !ctx.references) return null;
  return normalizeReferenceValue(mapGet(ctx.references, normalizeLabel(label)));
}

// ---------------------------------------------------------------------------
// Abbreviations
// ---------------------------------------------------------------------------

// Split `raw` into an array of string parts and {html} parts, replacing
// case-sensitive, word-boundary occurrences of each abbreviation.
function applyAbbreviations(raw, abbreviations) {
  let parts = [raw];
  for (const [abbr, title] of mapEntries(abbreviations)) {
    if (!abbr) continue;
    const abbrStr = String(abbr);
    const replacement =
      '<abbr title="' + escapeAll(String(title)) + '">' +
      escapeText(abbrStr) + '</abbr>';
    const next = [];
    for (const part of parts) {
      if (typeof part !== 'string') {
        next.push(part);
        continue;
      }
      let cursor = 0;
      let idx = part.indexOf(abbrStr, cursor);
      while (idx !== -1) {
        const before = idx > 0 ? part[idx - 1] : '';
        const afterIdx = idx + abbrStr.length;
        const after = afterIdx < part.length ? part[afterIdx] : '';
        if (!isWordChar(before) && !isWordChar(after)) {
          if (idx > cursor) next.push(part.slice(cursor, idx));
          next.push({ html: replacement });
          cursor = afterIdx;
        }
        idx = part.indexOf(abbrStr, idx + 1);
      }
      if (cursor === 0) {
        next.push(part);
      } else if (cursor < part.length) {
        next.push(part.slice(cursor));
      }
    }
    parts = next;
  }
  return parts;
}

// ---------------------------------------------------------------------------
// Low-level scanners
// ---------------------------------------------------------------------------

// Find a run of exactly `n` backticks at or after `from`; return its start
// index or -1.
function findBacktickClose(src, from, n) {
  let j = from;
  while (j < src.length) {
    if (src[j] === '`') {
      let m = 0;
      while (src[j + m] === '`') m++;
      if (m === n) return j;
      j += m;
    } else {
      j++;
    }
  }
  return -1;
}

// Match a balanced '[' ... ']' starting at src[i] === '['. Backslash-escaped
// chars are skipped. Returns {content, end} (end = index after ']') or null.
function matchBrackets(src, i) {
  let depth = 0;
  let j = i;
  while (j < src.length) {
    const ch = src[j];
    if (ch === '\\' && j + 1 < src.length) {
      j += 2;
      continue;
    }
    if (ch === '[') depth++;
    else if (ch === ']') {
      depth--;
      if (depth === 0) {
        return { content: src.slice(i + 1, j), end: j + 1 };
      }
    }
    j++;
  }
  return null;
}

// Skip whitespace starting at j; return new index.
function skipWs(src, j) {
  while (j < src.length && isWhitespace(src[j])) j++;
  return j;
}

// Parse "( url 'title' )" starting at src[i] === '('. Returns
// {url, title, end} or null.
function parseInlineDestination(src, i) {
  let j = skipWs(src, i + 1);
  let url = '';
  if (src[j] === '<') {
    const gt = src.indexOf('>', j + 1);
    if (gt === -1) return null;
    const inner = src.slice(j + 1, gt);
    if (inner.indexOf('<') !== -1 || inner.indexOf('\n') !== -1) return null;
    url = inner;
    j = gt + 1;
  } else {
    let depth = 0;
    while (j < src.length) {
      const ch = src[j];
      if (ch === '\\' && j + 1 < src.length && isEscapable(src[j + 1])) {
        url += src[j + 1];
        j += 2;
        continue;
      }
      if (ch === '(') {
        depth++;
        url += ch;
        j++;
        continue;
      }
      if (ch === ')') {
        if (depth === 0) break;
        depth--;
        url += ch;
        j++;
        continue;
      }
      if (isWhitespace(ch)) break;
      url += ch;
      j++;
    }
  }
  j = skipWs(src, j);
  let title = null;
  const ch = src[j];
  if (ch === '"' || ch === "'") {
    const quote = ch;
    let k = j + 1;
    let t = '';
    let closed = false;
    while (k < src.length) {
      if (src[k] === '\\' && k + 1 < src.length) {
        t += src[k] + src[k + 1];
        k += 2;
        continue;
      }
      if (src[k] === quote) {
        closed = true;
        break;
      }
      t += src[k];
      k++;
    }
    if (!closed) return null;
    title = t;
    j = k + 1;
  } else if (ch === '(') {
    let k = j + 1;
    let t = '';
    let closed = false;
    while (k < src.length) {
      if (src[k] === ')') {
        closed = true;
        break;
      }
      t += src[k];
      k++;
    }
    if (!closed) return null;
    title = t;
    j = k + 1;
  }
  j = skipWs(src, j);
  if (src[j] !== ')') return null;
  return { url, title, end: j + 1 };
}

// Find an emphasis closer for `marker` of length >= `need`, at or after
// `from`. Skips backslash escapes and code spans. Returns closer run start
// or -1.
function findEmphasisClose(src, from, marker, need) {
  let j = from;
  while (j < src.length) {
    const ch = src[j];
    if (ch === '\\' && j + 1 < src.length) {
      j += 2;
      continue;
    }
    if (ch === '`') {
      let m = 0;
      while (src[j + m] === '`') m++;
      const close = findBacktickClose(src, j + m, m);
      j = close >= 0 ? close + m : j + m;
      continue;
    }
    if (ch === marker) {
      let m = 0;
      while (src[j + m] === marker) m++;
      const before = j > 0 ? src[j - 1] : '';
      if (m >= need && before && !isWhitespace(before)) {
        if (marker !== '_') return j;
        const after = j + need < src.length ? src[j + need] : '';
        if (!isWordChar(after)) return j;
      }
      j += m;
      continue;
    }
    j++;
  }
  return -1;
}

// ---------------------------------------------------------------------------
// Inline token handlers
// ---------------------------------------------------------------------------

// Try to parse a link or image starting at src[i] === '['. `isImage`
// indicates a preceding '!'. Returns {label, url, title, end} or null.
function parseLinkOrImage(src, i, ctx) {
  const labelMatch = matchBrackets(src, i);
  if (!labelMatch) return null;
  const label = labelMatch.content;
  let j = labelMatch.end;
  if (src[j] === '(') {
    const dest = parseInlineDestination(src, j);
    if (!dest) return null;
    return { label, url: dest.url, title: dest.title, end: dest.end };
  }
  let refLabel = null;
  let end = j;
  if (src[j] === '[') {
    const refMatch = matchBrackets(src, j);
    if (refMatch) {
      refLabel = refMatch.content === '' ? label : refMatch.content;
      end = refMatch.end;
    }
  }
  if (refLabel === null) refLabel = label; // collapsed/shortcut reference
  const ref = lookupReference(ctx, refLabel);
  if (!ref) return null;
  return { label, url: ref.url, title: ref.title, end };
}

function renderLink(result, ctx, mode) {
  const inner = renderInline(result.label, ctx, mode);
  if (mode !== 'html') return inner;
  let out = '<a href="' + escapeAll(result.url) + '"';
  if (result.title != null) {
    out += ' title="' + escapeAll(processEscapes(result.title)) + '"';
  }
  return out + '>' + inner + '</a>';
}

function renderImage(result, ctx, mode) {
  if (mode !== 'html') return ''; // images are dropped entirely for TOC text
  const alt = escapeAll(processEscapes(result.label));
  let out = '<img alt="' + alt + '" src="' + escapeAll(result.url) + '"';
  if (result.title != null) {
    out += ' title="' + escapeAll(processEscapes(result.title)) + '"';
  }
  return out + ' />';
}

// Encode every character of an email address (or mailto: href) as decimal
// HTML entities, matching the deterministic form of Python-Markdown's
// email obfuscation.
function encodeEmail(s) {
  let out = '';
  for (let i = 0; i < s.length; i++) {
    out += '&#' + s.charCodeAt(i) + ';';
  }
  return out;
}

// Try to parse an autolink / raw HTML construct starting at src[i] === '<'.
// Returns {html, plain, end} or null. `plain` is used for TOC text modes.
function parseAngle(src, i, ctx, mode) {
  const rest = src.slice(i);

  // HTML comment <!-- ... -->
  if (rest.startsWith('<!--')) {
    const close = src.indexOf('-->', i + 4);
    if (close === -1) return null;
    return { html: src.slice(i, close + 3), plain: '', end: close + 3 };
  }
  // CDATA <![CDATA[ ... ]]>
  if (rest.startsWith('<![CDATA[')) {
    const close = src.indexOf(']]>', i + 9);
    if (close === -1) return null;
    return { html: src.slice(i, close + 3), plain: '', end: close + 3 };
  }
  // Processing instruction <? ... ?>
  if (rest.startsWith('<?')) {
    const close = src.indexOf('?>', i + 2);
    if (close === -1) return null;
    return { html: src.slice(i, close + 2), plain: '', end: close + 2 };
  }
  // Declaration <! ... >
  if (rest.startsWith('<!')) {
    const close = src.indexOf('>', i + 2);
    if (close === -1) return null;
    return { html: src.slice(i, close + 1), plain: '', end: close + 1 };
  }

  // Autolink <scheme://...> for http/https/ftp (case-insensitive).
  const lower = rest.toLowerCase();
  let schemeLen = 0;
  if (lower.startsWith('<http://')) schemeLen = 7;
  else if (lower.startsWith('<https://')) schemeLen = 8;
  else if (lower.startsWith('<ftp://')) schemeLen = 6;
  if (schemeLen > 0) {
    let j = i + 1 + schemeLen;
    let ok = j < src.length;
    while (j < src.length && src[j] !== '>') {
      const ch = src[j];
      if (ch === '<' || isWhitespace(ch)) {
        ok = false;
        break;
      }
      j++;
    }
    if (ok && src[j] === '>') {
      const url = src.slice(i + 1, j);
      const text = mode === 'slug' ? url : escapeText(url);
      return {
        html: '<a href="' + escapeAll(url) + '">' + escapeText(url) + '</a>',
        plain: text,
        end: j + 1,
      };
    }
    return null;
  }

  // Email autolink <addr@host>.
  {
    let j = i + 1;
    let atCount = 0;
    let ok = j < src.length;
    while (j < src.length && src[j] !== '>') {
      const ch = src[j];
      if (ch === '<' || isWhitespace(ch)) {
        ok = false;
        break;
      }
      if (ch === '@') atCount++;
      j++;
    }
    const body = src.slice(i + 1, j);
    const atIdx = body.indexOf('@');
    if (
      ok && src[j] === '>' && atCount === 1 && atIdx > 0 &&
      atIdx < body.length - 1
    ) {
      return {
        html: '<a href="' + encodeEmail('mailto:' + body) + '">' +
          encodeEmail(body) + '</a>',
        plain: mode === 'slug' ? body : escapeText(body),
        end: j + 1,
      };
    }
  }

  // Raw HTML tag </?letter ... > (no '<' or newline inside).
  {
    let j = i + 1;
    if (src[j] === '/') j++;
    if (j < src.length && isAsciiLetter(src[j])) {
      let k = j + 1;
      let ok = true;
      while (k < src.length && src[k] !== '>') {
        if (src[k] === '<') {
          ok = false;
          break;
        }
        k++;
      }
      if (ok && src[k] === '>') {
        return { html: src.slice(i, k + 1), plain: '', end: k + 1 };
      }
    }
  }

  return null;
}

// Try to parse emphasis at src[i] ('*' or '_'). Returns {html, plain, end}
// or null when the run cannot open emphasis.
function parseEmphasis(src, i, ctx, mode) {
  const marker = src[i];
  let run = 0;
  while (src[i + run] === marker) run++;
  const prev = i > 0 ? src[i - 1] : '';
  for (const need of [3, 2, 1]) {
    if (need > run) continue;
    // Underscore emphasis is not allowed intraword.
    if (marker === '_' && prev && isWordChar(prev)) continue;
    const contentStart = i + need;
    const next = contentStart < src.length ? src[contentStart] : '';
    if (!next || isWhitespace(next)) continue;
    const close = findEmphasisClose(src, contentStart, marker, need);
    if (close < 0) continue;
    const inner = renderInline(src.slice(contentStart, close), ctx, mode);
    if (mode !== 'html') {
      return { html: inner, plain: inner, end: close + need };
    }
    let html;
    if (need === 3) html = '<strong><em>' + inner + '</em></strong>';
    else if (need === 2) html = '<strong>' + inner + '</strong>';
    else html = '<em>' + inner + '</em>';
    return { html, plain: inner, end: close + need };
  }
  return null;
}

// ---------------------------------------------------------------------------
// Core renderer
// ---------------------------------------------------------------------------

// mode: 'html' | 'plain' | 'slug'
function renderInline(src, ctx, mode) {
  src = normalizeNewlines(src);
  const out = [];
  let buf = '';

  function flushBuf() {
    if (!buf) return;
    if (mode === 'slug') {
      out.push(buf);
    } else if (mode === 'html' && ctx && ctx.abbreviations) {
      for (const part of applyAbbreviations(buf, ctx.abbreviations)) {
