    if (ch === '<') {
      const angle = parseAngle(src, i, ctx, mode);
      if (angle) {
        flushBuf();
        out.push(mode === 'html' ? angle.html : angle.plain);
        i = angle.end;
        continue;
      }
      buf += ch;
      i++;
      continue;
    }

    // Entities.
    if (ch === '&') {
      const len = entityLengthAt(src, i);
      if (len > 0) {
        const entity = src.slice(i, i + len);
