          const decoded = decodeEntityBody(entity.slice(1, -1));
          buf += decoded != null ? decoded : entity;
        } else {
          flushBuf();
          out.push(entity);
        }
        i += len;
      } else {
        buf += ch; // escaped at flush (&amp;), raw in slug mode
        i++;
      }
      continue;
    }

    // Line breaks: 2+ trailing spaces before \n produce a hard break.
    if (ch === '\n') {
      let spaces = 0;
      while (spaces < buf.length && buf[buf.length - 1 - spaces] === ' ') {
        spaces++;
      }
      if (spaces >= 2) {
        buf = buf.slice(0, buf.length - 2); // keep spaces - 2
        flushBuf();
