    if (ch === '*' || ch === '_') {
      const em = parseEmphasis(src, i, ctx, mode);
      if (em) {
        flushBuf();
        out.push(mode === 'html' ? em.html : em.plain);
        i = em.end;
        continue;
      }
      buf += ch;
      i++;
      continue;
    }

    buf += ch;
    i++;
  }

  flushBuf();
  return out.join('');
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Parse inline Markdown to HTML.
 * context: { references, abbreviations, footnoteRef, state, extensions }
 */
export function parseInline(text, context = {}) {
  const ctx = resolveContext(context);
  return renderInline(String(text), ctx, 'html');
}

/**
 * Plain-text rendering of inline Markdown, for TOC names and slugs.
 * options.forSlug: decode entities and emit raw text (for slugify input).
 * Default (TOC HTML) mode: strip tags, drop images entirely, keep link
 * labels, preserve entity spelling, HTML-safe output.
 */
export function plainTextForInline(text, options = {}) {
  const ctx = resolveContext(options.context || {});
  const mode = options && options.forSlug ? 'slug' : 'plain';
  return renderInline(String(text), ctx, mode);
}

